-- Expand DAEHAN grade-3 new-character example-word coverage (batch 1).
with words(word,reading,meaning,child_explanation,chars) as (values
('각력','각력','다리의 힘','걷거나 뛸 때 쓰는 다리의 힘',array['脚','力']),('갈수','갈수','물이 줄어듦','가뭄 등으로 강이나 시내의 물이 줄어드는 것',array['渴','水']),('감행','감행','어려움을 무릅쓰고 행함','어려움이 있어도 용기를 내어 실행하는 것',array['敢','行']),('개근','개근','빠짐없이 출석함','정해진 날에 한 번도 빠지지 않고 출석하는 것',array['皆','勤']),('거주','거주','일정한 곳에서 삶','어떤 곳에 자리 잡고 생활하는 것',array['居','住']),('건곤','건곤','하늘과 땅','하늘과 땅을 함께 이르는 말',array['乾','坤']),('견고','견고','단단하고 튼튼함','쉽게 부서지거나 흔들리지 않을 만큼 튼튼한 것',array['堅','固']),('경면','경면','거울의 면','거울에서 모습을 비추는 면',array['鏡','面']),('경이','경이','놀랍고 신기함','뜻밖의 일을 보고 놀랍고 신기하게 느끼는 것',array['驚','異']),('계육','계육','닭고기','음식으로 먹는 닭의 고기',array['鷄','肉']),('계단','계단','높이가 다른 곳을 오르내리는 시설','여러 단으로 만들어 오르내릴 수 있게 한 시설',array['階','段']),('고독','고독','홀로 있어 외로움','혼자라고 느껴 쓸쓸하고 외로운 상태',array['孤','獨']),('곡물','곡물','먹는 곡식','쌀이나 보리처럼 사람이 먹는 곡식을 통틀어 이르는 말',array['穀','物']),('곤지','곤지','땅을 가리키는 말','옛말에서 땅을 뜻하여 이르는 말',array['坤','地']),('궁극','궁극','마지막에 이르는 끝','더 나아갈 수 없는 마지막 단계나 상태',array['窮','極']),('권고','권고','어떤 일을 하도록 권함','좋다고 생각하는 일을 하도록 말해 주는 것',array['勸','告']),('권책','권책','책 한 권','한 권으로 묶인 책을 이르는 말',array['卷','冊']),('근로','근로','부지런히 일함','생활에 필요한 것을 얻기 위해 성실하게 일하는 것',array['勤','勞']),('기다','기다','수량이 많음','수가 많거나 여러 가지임을 나타내는 말',array['幾','多']),('기왕','기왕','이미 그렇게 된 바에','어떤 일이 이미 이루어진 뒤를 나타내는 말',array['旣','往']),('단지','단지','다만','다른 것이 아니라 오직 그것뿐이라는 뜻',array['但','只']),('단계','단계','일이 진행되는 차례','일이 차례대로 진행될 때 나뉘는 과정',array['段','階']),('난백','난백','알의 흰자','달걀 같은 알에서 흰 부분',array['卵','白']),('관람','관람','구경하여 봄','공연이나 전시 등을 직접 가서 보는 것',array['觀','覽']),('파랑','파랑','물결','물 위에 일어나는 크고 작은 물결',array['波','浪'])
), upserted as (insert into public.hanja_words(word,reading,meaning,child_explanation,content_status,source_note) select word,reading,meaning,child_explanation,'PUBLISHED','3급 신규 예시어 보강 1차 · 앱 자체 쉬운 뜻풀이 · 2026-10-06' from words on conflict(word,reading,meaning) do update set child_explanation=excluded.child_explanation,content_status='PUBLISHED',source_note=excluded.source_note returning id,word,reading,meaning)
insert into public.hanja_word_map(word_id,hanja_id,position) select hw.id,h.id,u.ord::integer from words w join upserted hw on hw.word=w.word and hw.reading=w.reading and hw.meaning=w.meaning cross join lateral unnest(w.chars) with ordinality u(ch,ord) join public.hanja h on h.character=u.ch on conflict do nothing;